      Insert: {
        code: InstrumentCode;
        label: string;
        kind: InstrumentKind;
        venue: Venue;
        legs: number;
        settlement_rule: SettlementRule;
        option_type?: OptionType;
        product_from_trade?: boolean;
        tradable?: boolean;
      };
      Update: {
        label?: string;
        tradable?: boolean;
      };
