    position_marks: {
      Args: { p_user_id: string };
      Returns: Array<{
        position_id: string;
        mark_price: number | null;
        mark_timestamp: string | null;
      }>;
    };
    mint_username: {
      Args: { p_email: string; p_user_id: string };
      Returns: string;
    };
